void NumericField::show()
{
	bool isTracing = Debug::isTracing(HobString("NumericMessages"));

	if (isTracing == false)
	{
#if defined(LINUX_FIX)
		Debug::addTraceCategory( std::string("NumericMessages") );
#else
		Debug::addTraceCategory("NumericMessages");
#endif
	}

	Debug::trace("NumericMessages", "NumericField: ");

	EvolMessage::show();

	Debug::trace("NumericMessages", "field data: ");
	Debug::trace("NumericMessages", fieldData_);
	
	if (nmFieldType_ == NmTare)
	{
		Debug::trace("NumericMessages", "update tare field");
	}
	else if (nmFieldType_ == NmWeight)
	{
		Debug::trace("NumericMessages", "update weight field");
	}
	else if (nmFieldType_ == NmUnitPrice)
	{
		Debug::trace("NumericMessages", "update unit price field");
	}
	else if (nmFieldType_ == NmTotalPrice)
	{
		Debug::trace("NumericMessages", "update total price field");
	}
	else if (nmFieldType_ == NmNumeric)
	{
		Debug::trace("NumericMessages", "update numeric field");
	}
	else
	{
		Debug::trace("NumericMessages", HobString("invalid field ") +
											 HobString(Integer::toString((UINT16) nmFieldType_)));
	}


	if (isTracing == false)
	{
#if defined(LINUX_FIX)
		Debug::removeTraceCategory( std::string("NumericMessages") );
#else
		Debug::removeTraceCategory("NumericMessages");
#endif
	}

}

