int NumericField::fillPeripheralMessage(NmFieldMsg& nmFieldMsg)
{

	nmFieldMsg.nmEvent = (UINT8)eventType;
	nmFieldMsg.pad0 = 0;
	nmFieldMsg.field = (UINT8)nmFieldType_;
	nmFieldMsg.pad1 = 0;

	memset(nmFieldMsg.fieldData, 0, MAX_NUMERIC_STRING);
	strcpy((char *)nmFieldMsg.fieldData, (const char *)fieldData_);

	return sizeof(nmFieldMsg);
}
